-- Synthetic SQLite fixture generated by the stores at main c70d957.
PRAGMA foreign_keys=OFF;
CREATE TABLE blobs (
    hash TEXT PRIMARY KEY, bytes BLOB NOT NULL
  ) STRICT;
CREATE TABLE publications (
    id INTEGER PRIMARY KEY, vault TEXT NOT NULL, revision TEXT NOT NULL, title TEXT NOT NULL,
    kind TEXT NOT NULL, published_at INTEGER NOT NULL, schema_id TEXT NOT NULL, schema_version TEXT NOT NULL,
    manifest_hash TEXT NOT NULL REFERENCES blobs(hash), input_hash TEXT NOT NULL REFERENCES blobs(hash),
    allow_model INTEGER NOT NULL CHECK(allow_model IN (0, 1)), index_hash TEXT,
    UNIQUE(vault, revision)
  ) STRICT;
CREATE TABLE vaults (
    id TEXT PRIMARY KEY, publication INTEGER NOT NULL REFERENCES publications(id)
  ) STRICT;
CREATE TABLE passages (
    id INTEGER PRIMARY KEY, publication INTEGER NOT NULL REFERENCES publications(id),
    passage TEXT NOT NULL, source TEXT NOT NULL, locator TEXT NOT NULL, hash TEXT NOT NULL REFERENCES blobs(hash),
    UNIQUE(publication, passage)
  ) STRICT;
CREATE VIRTUAL TABLE passage_index USING fts5(
    parts, specs, words, singles, publication UNINDEXED, tokenize='unicode61 remove_diacritics 0'
  );
CREATE TABLE inactive_vaults (
  vault TEXT PRIMARY KEY REFERENCES vaults(id)
) STRICT;
CREATE TABLE review_uploads (
  hash TEXT PRIMARY KEY REFERENCES blobs(hash)
) STRICT;
CREATE TABLE review_schemas (
  vault TEXT NOT NULL, version TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY(vault, version)
) STRICT;
CREATE TABLE review_schema_heads (
  vault TEXT PRIMARY KEY, version TEXT NOT NULL,
  FOREIGN KEY(vault, version) REFERENCES review_schemas(vault, version)
) STRICT;
CREATE TABLE reviews (
  id TEXT PRIMARY KEY, vault TEXT NOT NULL, parent TEXT, original TEXT NOT NULL, draft TEXT NOT NULL,
  edit INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', publication TEXT
) STRICT;
CREATE TABLE review_edits (
  review TEXT NOT NULL REFERENCES reviews(id), edit INTEGER NOT NULL, draft TEXT NOT NULL, PRIMARY KEY(review, edit)
) STRICT;
CREATE TABLE notification_intents (
  review TEXT PRIMARY KEY REFERENCES reviews(id), vault TEXT NOT NULL, revision TEXT NOT NULL
) STRICT;
CREATE TABLE ingest_jobs (
  id TEXT PRIMARY KEY, payload TEXT NOT NULL, lease TEXT, expires INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE ingest_effects (
  job TEXT PRIMARY KEY REFERENCES ingest_jobs(id), review TEXT NOT NULL REFERENCES reviews(id)
) STRICT;
CREATE TABLE benchmark_sets (
    vault TEXT NOT NULL, name TEXT NOT NULL, questions TEXT NOT NULL, PRIMARY KEY(vault, name)
  ) STRICT;
CREATE TABLE vault_classifications (
    vault_id TEXT PRIMARY KEY REFERENCES vaults(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    classification TEXT NOT NULL DEFAULT 'unclassified' CHECK(classification IN ('unclassified', 'public', 'confidential')),
    updated_at INTEGER NOT NULL
  ) STRICT;
CREATE TABLE bi_job_ownership (
  job_id TEXT PRIMARY KEY REFERENCES ingest_jobs(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  agent_id TEXT NOT NULL CHECK(agent_id='bi'), work_id TEXT, origin TEXT NOT NULL
    CHECK(origin IN ('telegram','owner','schedule','legacy'))
) STRICT;
CREATE TABLE review_provenance (
  review_id TEXT PRIMARY KEY REFERENCES reviews(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  agent_id TEXT NOT NULL CHECK(agent_id='bi'), origin TEXT NOT NULL CHECK(origin IN ('telegram','owner','schedule','legacy')),
  source_key TEXT, run_id TEXT, delivery_destination TEXT CHECK(json_valid(delivery_destination)),
  CHECK(origin<>'telegram' OR (source_key IS NOT NULL AND delivery_destination IS NOT NULL))
) STRICT;
CREATE TABLE bi_publication_ownership (
  publication_id INTEGER PRIMARY KEY REFERENCES publications(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  agent_id TEXT NOT NULL CHECK(agent_id='bi'), review_id TEXT REFERENCES reviews(id) ON DELETE RESTRICT ON UPDATE RESTRICT
) STRICT;
